    doc.setDrawColor(24, 20, 16);
    doc.setLineWidth(0.5);
    doc.line(tx, y - 2, vx, y - 2);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.setTextColor(24, 20, 16);
    doc.text("TOTAL", tx, y + 4);
